{
  "pairs": [
    {"reference_id": "R1", "candidate_id": "C1", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The bounce is physically impossible", "candidate_evidence": "The rugby ball compresses and morphs into an almost spherical shape while resting on the grass", "basis": "explicit_separation", "reason_ko": "참조는 공의 튀어 오르는 동작(bounce)이 물리적으로 불가능하다는 결함을 기술하는 반면, 후보는 잔디 위에 멈춰 있는(resting on the grass) 동안 발생하는 형태 변형 및 압축을 기술하므로 서로 다른 상호작용 및 현상입니다.", "separation_basis": "different_interaction"},
    {"reference_id": "R1", "candidate_id": "C2", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The bounce is physically impossible", "candidate_evidence": "The rugby ball disappears from the frame and then reappears smaller in the background further away without consistent motion.", "basis": "explicit_separation", "reason_ko": "참조는 바운스 동작 자체의 물리적 이상을 지적하지만, 후보는 공이 프레임 밖으로 사라졌다가 배경에 다시 나타나는 소멸/재등장 현상을 기술하므로 대상의 이상 상호작용/동작이 서로 다릅니다.", "separation_basis": "different_interaction"},
    {"reference_id": "R1", "candidate_id": "C3", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The bounce is physically impossible", "candidate_evidence": "The rugby ball shifts between an elongated prolate spheroid and a nearly round ball shape while morphing its surface markings.", "basis": "explicit_separation", "reason_ko": "참조는 바운스 동작의 물리적 불가능성을 다루는 반면, 후보는 공의 형태 왜곡과 표면 마킹 모핑이라는 외형적 변형을 지적하므로 구별되는 결함입니다.", "separation_basis": "different_interaction"},
    {"reference_id": "R1", "candidate_id": "C5", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The bounce is physically impossible", "candidate_evidence": "The rugby ball rolls out of frame on the left, but then suddenly re-enters or spawns on the far left grass", "basis": "explicit_separation", "reason_ko": "참조는 바운스 모션의 물리적 오류를 지적하는 반면, 후보는 굴러서 프레임 밖으로 나간 뒤 갑자기 다시 생성되는 텔레포트/생성 현상을 기술하므로 동작 및 상호작용이 상이합니다.", "separation_basis": "different_interaction"},
    {"reference_id": "R1", "candidate_id": "C6", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The bounce is physically impossible", "candidate_evidence": "The shape, surface seams, and markings of the rugby ball morph irregularly across its trajectory", "basis": "explicit_separation", "reason_ko": "참조는 튀는 동작(bounce)의 물리 법칙 위배를 기술하지만, 후보는 이동 궤적 동안 형태, 솔기, 마킹이 왜곡되는 외형 모핑을 기술하므로 서로 다른 이상 현상입니다.", "separation_basis": "different_interaction"},
    {"reference_id": "R1", "candidate_id": "C7", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The bounce is physically impossible", "candidate_evidence": "Rugby ball exits frame left, then abruptly reappears in the background at a distance rolling on the field.", "basis": "explicit_separation", "reason_ko": "참조는 바운스의 물리적 불가능성을 언급하나, 후보는 화면 왼쪽으로 나간 후 먼 배경에서 갑자기 재등장하는 위치/연속성 결함을 기술하므로 구별되는 사건입니다.", "separation_basis": "different_interaction"},
    {"reference_id": "R1", "candidate_id": "C9", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "The bounce is physically impossible", "candidate_evidence": "럭비공이 왼쪽 가장자리로 이동하며 점점 작아지다가 5.708초경 프레임에서 완전히 사라짐.", "basis": "explicit_separation", "reason_ko": "참조의 바운스 동작 이상과 후보의 왼쪽 가장자리로 이동 후 프레임 이탈/사라짐 현상은 물리적 동작 및 상호작용 측면에서 서로 명확히 구분됩니다.", "separation_basis": "different_interaction"}
  ]
}

